#!/usr/bin/env python3
# -*- coding: utf-8 -*-
"""
Please read README.md
Generated by deepSeek v4.1-Flash
Verified and tested by ELXT
"""

VERSION='v1.0 -20261002'

import argparse
import ast
import base64
import math
import os
import re
import struct
import sys
import zipfile
import zlib
from collections import OrderedDict

# --------------------------------------------------------------------------
# INI parsing (mirrors the engine's loader, see module docstring)
# --------------------------------------------------------------------------

INI_EXTENSIONS = (".ini", ".template")

# Exact section names the engine understands.
RECOGNIZED_SECTION_NAMES = frozenset((
    "core", "graphics", "attack", "movement", "ai",
))
# Section prefixes (matched as "<prefix>_<suffix>").  Kept disjoint from
# RECOGNIZED_SECTION_NAMES so every name is tested exactly once.
# Taken from the RWini VSCode plugin's section database
# (db/dataBaseSection.json).
RECOGNIZED_SECTION_PREFIXES = frozenset((
    "canBuild", "turret", "projectile", "arm", "leg", "attachment",
    "effect", "animation", "action", "hiddenAction", "placementRule",
    "resource", "global_resource", "decal", "comment", "template",
))
# mod-info.txt is special: only these sections are valid in it.
MOD_INFO_SECTIONS = frozenset(("mod", "maps", "music"))

# The engine also reads @global/@define/@memory directives that appear at file
# level, i.e. before the first [section].  They are kept in this sentinel bucket
# so they are not lost (they are written back without a section header).
TOP_LEVEL_SECTION = ""


def is_recognized_section(name):
    if name in RECOGNIZED_SECTION_NAMES:
        return True
    for prefix in RECOGNIZED_SECTION_PREFIXES:
        if name.startswith(prefix + "_"):
            return True
    return False


def section_allowed(name, file_name):
    """Whether a section is valid inside the given file."""
    if name == TOP_LEVEL_SECTION:
        return True
    if is_modinfo(file_name):
        # mod-info.txt may only contain [mod], [maps], [music].
        return name in MOD_INFO_SECTIONS
    return is_recognized_section(name)


def is_text_config(name):
    """True for files the engine loads as INI text."""
    low = name.lower()
    if low.endswith(INI_EXTENSIONS):
        return True
    return low.endswith("mod-info.txt")


def parse_ini(text):
    """Parse INI text the way the engine does.

    Returns an OrderedDict {section_name: OrderedDict{key: value}}.
    Section order = first appearance, key order = first appearance,
    duplicate keys keep the last value at their first position.
    """
    # The engine reads lines with Java's BufferedReader.readLine(), which
    # treats CR, LF and CRLF all as line separators.  Some obfuscated mods
    # rely on CR-only separators, so split on all three.
    text = text.replace("\ufeff", "")       # BOM / zero-width pad, not a char
    lines = re.split(r"\r\n|\r|\n", text)
    sections = OrderedDict()
    current = None          # current section name, or None while inside/after
    i = 0
    n = len(lines)
    while i < n:
        raw = lines[i]
        i += 1
        s = raw.strip()
        if s == "" or s[0] == "#":
            continue

        skip = (s[0] == '"')          # '"' at line start -> comment
        in_quotes = False
        buf = []
        piece = s
        while True:
            j = 0
            ln = len(piece)
            while j >= 0:
                k = piece.find('"""', j)
                if k < 0:
                    m = k
                    k = ln
                else:
                    in_quotes = not in_quotes
                    m = k + 3
                if not skip:
                    buf.append(piece[j:k])
                j = m
            if in_quotes:
                if i >= n:
                    break
                piece = lines[i].strip()
                i += 1
            else:
                break
        if skip:
            continue
        s = "".join(buf).strip()
        if s == "":
            continue

        # section header: '[...]' with ']' as the very last character
        if s[0] == "[":
            close = s.find("]", 1)
            if close == len(s) - 1:
                name = s[1:close].strip()
                if name.startswith("comment_"):
                    current = None          # engine ignores the whole block
                else:
                    sections.setdefault(name, OrderedDict())
                    current = name
                continue

        if current is None:
            continue

        split = -1
        for idx, ch in enumerate(s):
            if ch == ":" or ch == "=":
                split = idx
                break
        if split < 0:
            continue

        key = s[:split].strip()
        value = s[split + 1:].strip()
        sections[current][key] = value     # last value wins, position kept
    return sections


def dump_ini(sections):
    """Serialise sections in the engine's writing style."""
    out = []
    for name, kv in sections.items():
        if not kv:
            continue
        if name == TOP_LEVEL_SECTION:
            # File-level directives have no [section] header.
            for k, v in kv.items():
                if out:
                    out.append("\n")
                out.append(k)
                out.append(":")
                out.append(v)
            continue
        if out:
            out.append("\n")
        out.append("[" + name + "]")
        for k, v in kv.items():
            out.append("\n")
            out.append(k)
            out.append(":")
            out.append(v)
    return "".join(out)


def referenced_sections(sections):
    """Collect section names referenced by one file's content."""
    refs = set()
    for secname, kv in sections.items():
        indexed = "_" in secname
        prefix = secname.split("_", 1)[0] if indexed else ""
        for key, value in kv.items():
            if key == "@copyFromSection":
                for token in value.split(","):
                    token = token.strip()
                    if token:
                        refs.add(token)
            elif key == "copyFrom" and indexed:
                # sibling copy: [leg_2] copyFrom: 1  ->  leg_1
                for token in value.split(","):
                    token = token.strip()
                    if token:
                        refs.add(prefix + "_" + token)
            for match in re.finditer(r"\$\{([^}]*)\}", value):
                for tok in _IDENT_RE.finditer(match.group(1)):
                    token = tok.group(0)
                    if "." in token:
                        sec = token.split(".", 1)[0]
                        if sec != "section":
                            refs.add(sec)
    return refs


def strip_unknown_sections(sections_by_name):
    """Drop arbitrary sections the engine cannot use and nothing references.

    A section is kept when its name is engine-recognised, or when any file
    references it through @copyFromSection / sibling copyFrom / ${sec.key}.
    Returns the number of removed sections.
    """
    refs = set()
    for sections in sections_by_name.values():
        refs |= referenced_sections(sections)

    removed = 0
    for file_name, sections in sections_by_name.items():
        for name in list(sections.keys()):
            if section_allowed(name, file_name) or name in refs:
                continue
            del sections[name]
            removed += 1
    return removed


def _resolve_member_path(value, curdir, root, member_set):
    """Return ``value`` without its trailing '/' if it points at a member.

    ``value`` may carry SHADOW:/ROOT: prefixes.  SHARED:/CORE: are built-in
    and never touched.  Returns None when it does not resolve to a file.
    """
    prefix = ""
    rest = value
    if rest.startswith("SHADOW:"):
        prefix = "SHADOW:"
        rest = rest[len("SHADOW:"):]
    if rest.startswith("ROOT:"):
        prefix += "ROOT:"
        rest = rest[len("ROOT:"):]
    if rest.startswith(("SHARED:", "CORE:")):
        return None
    stripped = rest.rstrip("/")
    if not stripped:
        return None
    if prefix.endswith("ROOT:"):
        bases = [root]
    else:
        bases = [curdir]
        parent = curdir.rstrip("/").rsplit("/", 1)[0] + "/" if "/" in curdir.rstrip("/") else ""
        if parent and parent != curdir:
            bases.append(parent)
        if root:
            bases.append(root)
    for base in bases:
        if normpath(base + stripped).lower() in member_set:
            return prefix + stripped
    return None


def normalize_reference_paths(sections_by_name, members, root):
    """Drop the trailing '/' from a reference only when it points at a file.

    A "fake folder" pack stores a file as "name/" and the ini refers to it with
    the same trailing slash.  The reader strips the slash from member names, so
    such references must be stripped too or they no longer match.  We decide by
    resolving the value (honouring SHADOW:/ROOT: prefixes and the ini's own
    directory) and checking whether it matches a real member; a value that ends
    with '/' but is not a file (e.g. a directory like sourceFolder) is left as
    is.  Comma separated lists are handled per item.
    """
    if not members:
        return 0
    member_set = set(name.lower() for name in members)

    changed = 0
    for file_name, sections in sections_by_name.items():
        curdir = file_name.rsplit("/", 1)[0] + "/" if "/" in file_name else ""
        for sec in sections.values():
            for key in list(sec.keys()):
                # @define / @global (and other @ directives) carry arbitrary
                # values, so never treat them as file paths.  A global that
                # really holds a path is only corrected after expansion, when
                # its value lands on a normal key: use --resolve for that.
                if key.startswith("@"):
                    continue
                value = sec[key]
                if not value.endswith("/"):
                    continue
                if "," not in value:
                    resolved = _resolve_member_path(value, curdir, root, member_set)
                    if resolved is not None:
                        sec[key] = resolved
                        changed += 1
                    continue
                parts = value.split(",")
                hit = False
                for i, part in enumerate(parts):
                    if part.endswith("/"):
                        resolved = _resolve_member_path(part, curdir, root, member_set)
                        if resolved is not None:
                            parts[i] = resolved
                            hit = True
                if hit:
                    sec[key] = ",".join(parts)
                    changed += 1
    return changed


# --------------------------------------------------------------------------
# Key-name validation against keyList.txt
# --------------------------------------------------------------------------

KEYLIST_FILENAME = "keyList.txt"
_KEY_HEADER_RE = re.compile(r"^(?:\[[^\]]+\])+$")
_KEY_NOTE_PREFIXES = (
    "TYPE含", "[animationKey]同", "N为任意内容",
    "可以存在于任何节", "X为任意英文内容",
)

# Compact copy of keyList.txt (note lines removed, then zlib + base64) so the
# script works without the external file.  Fill it with embed_keylist.py.
KEYLIST_INTERNAL_B64 = "... (line truncated to 2000 chars)


def internal_keylist_text():
    """Return the embedded key list as plain text."""
    if not KEYLIST_INTERNAL_B64:
        raise ValueError("embedded key list is empty")
    raw = base64.b64decode(KEYLIST_INTERNAL_B64.encode("ascii"))
    return zlib.decompress(raw).decode("utf-8")


def trim_keylist_text(text):
    """Drop blank and documentation lines from a key list."""
    lines = []
    for raw in text.split("\n"):
        line = raw.strip()
        if not line or line.startswith(_KEY_NOTE_PREFIXES):
            continue
        lines.append(line)
    return "\n".join(lines)


def parse_keylist_text(text):
    """Parse key list text into [(header_tokens, [key_patterns]), ...]."""
    groups = []
    current = None
    for raw in text.split("\n"):
        line = raw.strip()
        if not line:
            continue
        if line.startswith(_KEY_NOTE_PREFIXES):
            continue
        if _KEY_HEADER_RE.match(line):
            tokens = re.findall(r"\[([^\]]+)\]", line)
            groups.append((tokens, []))
            current = groups[-1][1]
            continue
        if current is not None:
            current.append(line)
    return groups


def load_keylist(path):
    """Parse a keyList.txt file into [(header_tokens, [key_patterns]), ...]."""
    text = open(path, "rb").read().decode("utf-8-sig", "replace")
    return parse_keylist_text(text)


class KeyValidator(object):
    """Validate key names against the section/key list."""

    def __init__(self, text):
        self.groups = parse_keylist_text(text)
        self.action_keys = set()
        self.canbuild_keys = set()
        for tokens, keys in self.groups:
            if "hiddenAction_NAME" in tokens:
                self.action_keys.update(
                    k for k in keys if re.match(r"^[A-Za-z_]", k))
            if "canBuild_NAME" in tokens:
                self.canbuild_keys.update(
                    k for k in keys if re.match(r"^[A-Za-z_]", k))
        self._cache = {}

    def _regex(self, pattern):
        if pattern.endswith("isLocked:"):
            return None
        if pattern == "animation_TYPE_[animationKey]":
            return r"^animation_(?:idle|moving|attack)_.+$"
        m = re.match(r"^mutatorN_(.*)$", pattern)
        if m:
            return r"^mutator.*_" + re.escape(m.group(1)) + r"$"
        p = pattern
        p = p.replace("#", "ZZHASHZZ").replace("[Language]", "ZZLANGZZ")
        p = p.replace("[actionKey]", "ZZACTZZ").replace("[canBuildKey]", "ZZCBZZ")
        p = p.replace("[animationKey]", "ZZANIMZZ").replace("[time]", "ZZTIMEZZ")
        p = re.escape(p)
        p = p.replace("ZZHASHZZ", r"\d*").replace("ZZLANGZZ", r".+")
        p = p.replace("ZZACTZZ", "(?:" + "|".join(
            re.escape(k) for k in sorted(self.action_keys)) + ")")
        p = p.replace("ZZCBZZ", "(?:" + "|".join(
            re.escape(k) for k in sorted(self.canbuild_keys)) + ")")
        p = p.replace("ZZANIMZZ", r".+").replace("ZZTIMEZZ", r".+")
        return "^" + p + "$"

    @staticmethod
    def _section_matches(tokens, section):
        for token in tokens:
            if token == section:
                return True
            if token.endswith("_NAME") or token.endswith("_NANE"):
                prefix = token.rsplit("_", 1)[0]
                if section.startswith(prefix + "_"):
                    return True
                if prefix == "hiddenAction" and section.startswith("action_"):
                    return True
            if token.endswith("_#"):
                prefix = token.rsplit("_", 1)[0]
                if section.startswith(prefix + "_"):
                    return True
        return False

    def allowed(self, section, key):
        if key.startswith("@"):
            return True
        # template_/comment_ sections hold keys copied from other section
        # types, so they cannot be validated by name.
        if section.startswith(("template_", "comment_")):
            return True
        cached = self._cache.get((section, key))
        if cached is not None:
            return cached
        matched = False
        ok = False
        for tokens, keys in self.groups:
            if not self._section_matches(tokens, section):
                continue
            matched = True
            for pattern in keys:
                if pattern.endswith("isLocked:"):
                    base = pattern.split("name/pos/isLocked:")[0]
                    patterns = [base + s for s in ("name", "pos", "isLocked")]
                else:
                    patterns = [pattern]
                for pat in patterns:
                    rx = self._regex(pat)
                    if rx and re.match(rx, key):
                        ok = True
                        break
                if ok:
                    break
            if ok:
                break
        if not matched:
            ok = True     # no key list for this section -> cannot judge
        self._cache[(section, key)] = ok
        return ok

    def check(self, sections_by_name):
        """Return a list of (file, section, key) that are not allowed."""
        invalid = []
        for file_name, sections in sections_by_name.items():
            for section, kv in sections.items():
                for key in kv:
                    if not self.allowed(section, key):
                        invalid.append((file_name, section, key))
        return invalid


def find_external_keylist(in_path):
    """Find keyList.txt next to the script, then next to the input file."""
    here = os.path.dirname(os.path.abspath(__file__))
    for folder in (here, os.path.dirname(os.path.abspath(in_path))):
        cand = os.path.join(folder, KEYLIST_FILENAME)
        if os.path.isfile(cand):
            return cand
    return None


# --------------------------------------------------------------------------
# Optional expansion of ${...} macros and copyFrom inheritance
# --------------------------------------------------------------------------

_MATH_FUNCS = {"int", "cos", "sin", "sqrt"}
_IDENT_RE = re.compile(r"[A-Za-z_][A-Za-z0-9_.]*")
_TEMPLATE_NAME = "all-units.template"


def normpath(path):
    parts = []
    for seg in path.replace("\\", "/").split("/"):
        if seg in ("", "."):
            continue
        if seg == "..":
            if parts:
                parts.pop()
            continue
        parts.append(seg)
    return "/".join(parts)


def basename(name):
    return name.rsplit("/", 1)[-1]


def is_template_entry(name):
    return basename(name).lower() == _TEMPLATE_NAME


def is_modinfo(name):
    return basename(name).lower() == "mod-info.txt"


def truthy(value):
    return value is not None and value.strip().lower() in ("1", "true", "yes", "on")


def copy_sections(sections):
    return OrderedDict((k, OrderedDict(v)) for k, v in sections.items())


def merge_into(dst, src, inherited=False):
    """Merge src into dst with dst's existing keys taking precedence.

    Mirrors the engine's putIfAbsent merge, including the
    '@copyFrom_skipThisSection' guard on the section already present.

    ``inherited`` is used when merging inherited sources (copyFrom /
    all-units.template).  Two keys only ever belong to the file itself and
    must not be inherited:
      * '[core] dont_load'                 -> a copied unit would stop loading
      * '[...] @copyFrom_skipThisSection'  -> a merge-control flag
    """
    for secname, kv in src.items():
        core = (secname == "core")

        def inherited_only(k):
            return inherited and (k == "@copyFrom_skipThisSection"
                                  or (core and k == "dont_load"))

        if secname not in dst:
            dst[secname] = OrderedDict(
                (k, v) for k, v in kv.items() if not inherited_only(k))
            continue
        if truthy(dst[secname].get("@copyFrom_skipThisSection")):
            continue
        for k, v in kv.items():
            if inherited_only(k):
                continue
            dst[secname].setdefault(k, v)


class FileIndex(object):
    """Case-insensitive lookup of member names inside a mod."""

    def __init__(self, names):
        self.exact = set(names)
        self.lower = {}
        for n in names:
            self.lower.setdefault(n.lower(), n)

    def find(self, name):
        name = normpath(name)
        if name in self.exact:
            return name
        low = name.lower()
        if low in self.lower:
            return self.lower[low]
        for suffix in (".ini", ".template"):
            cand = name + suffix
            if cand in self.exact:
                return cand
            if cand.lower() in self.lower:
                return self.lower[cand.lower()]
        return None


def try_eval(expr):
    """Safely evaluate a small arithmetic expression, else return None.

    A comma means the value is a list (e.g. a footprint "x,y,w,h" or a macro
    fragment like "-1,"), never arithmetic, so it must be left untouched.
    """
    expr = expr.strip()
    if not expr or "," in expr:
        return None
    try:
        node = ast.parse(expr, mode="eval").body
    except SyntaxError:
        return None

    def ev(n):
        if isinstance(n, ast.Expression):
            return ev(n.body)
        if isinstance(n, ast.Constant) and isinstance(n.value, (int, float)):
            return n.value
        if isinstance(n, ast.BinOp):
            a, b = ev(n.left), ev(n.right)
            if isinstance(n.op, ast.Add):
                return a + b
            if isinstance(n.op, ast.Sub):
                return a - b
            if isinstance(n.op, ast.Mult):
                return a * b
            if isinstance(n.op, ast.Div):
                return a / b
            if isinstance(n.op, ast.Mod):
                return a % b
            if isinstance(n.op, ast.Pow):
                return a ** b
            raise ValueError
        if isinstance(n, ast.UnaryOp):
            v = ev(n.operand)
            if isinstance(n.op, ast.USub):
                return -v
            if isinstance(n.op, ast.UAdd):
                return v
            raise ValueError
        if isinstance(n, ast.Call):
            if not (isinstance(n.func, ast.Name) and len(n.args) == 1):
                raise ValueError
            name = n.func.id
            v = ev(n.args[0])
            if name == "int":
                return int(v)
            if name == "cos":
                return math.cos(v)
            if name == "sin":
                return math.sin(v)
            if name == "sqrt":
                return math.sqrt(v)
            raise ValueError
        raise ValueError

    try:
        return ev(node)
    except Exception:
        return None


def format_number(value):
    if isinstance(value, float) and value.is_integer():
        return str(int(value))
    if isinstance(value, float):
        return repr(value)
    return str(value)


class Resolver(object):
    """Resolve one mod's ini files to their effective (expanded) content."""

    def __init__(self, parsed, root, use_template):
        self.parsed = parsed
        self.index = FileIndex(parsed.keys())
        self.root = root
        self.use_template = use_template
        self.raw_cache = {}
        self.copyfrom_ok = {}
        self.stack = set()

    # -- path helpers ------------------------------------------------------
    def resolve_target(self, target, cur_name):
        t = target.replace("\\", "/").strip()
        if t.startswith("CORE:"):
            lib = t[5:].strip()
            for key in (lib, lib + ".ini"):
                found = self.index.find("assets/units/" + key)
                if found:
                    return found
            return None
        if t.startswith("ROOT:"):
            rel = normpath(t[5:])
            found = self.index.find(self.root + rel)
            if found:
                return found
            # `ROOT:` is relative to the directory that contains the mod
            # folder, so a reference often looks like
            # "ROOT:<mod folder>/file".  The packer flattens the mod folder
            # away, so retry after dropping leading path segments.
            segs = rel.split("/")
            for i in range(1, len(segs)):
                cand = "/".join(segs[i:])
                found = self.index.find(self.root + cand)
                if found:
                    return found
            return None
        curdir = cur_name.rsplit("/", 1)[0] + "/" if "/" in cur_name else ""
        return self.index.find(curdir + t)

    def find_template(self, cur_name):
        d = cur_name.rsplit("/", 1)[0] if "/" in cur_name else ""
        while True:
            cand = (d + "/" if d else "") + _TEMPLATE_NAME
            found = self.index.find(cand)
            if found:
                return found
            if not d:
                return None
            d = d.rsplit("/", 1)[0] if "/" in d else ""

    # -- main --------------------------------------------------------------
    def raw_merged(self, name):
        """Merge a file with its copyFrom chain / template, without expanding
        section copies, globals or macros yet (so that inherited directives
        stay available to the receiving file's context)."""
        if name in self.raw_cache:
            return self.raw_cache[name]
        if name in self.stack:          # cycle guard
            return OrderedDict()
        self.stack.add(name)
        own = copy_sections(self.parsed[name])

        copy_targets = []
        copyfrom_ok = True
        core = own.get("core")
        if core and core.get("copyFrom"):
            raw = core["copyFrom"].strip()
            if raw and raw.upper() != "IGNORE":
                for token in raw.split(","):
                    token = token.strip()
                    if not token:
                        continue
                    tname = self.resolve_target(token, name)
                    if tname and tname in self.parsed:
                        copy_targets.append(self.raw_merged(tname))
                    else:
                        copyfrom_ok = False

        # The engine only applies all-units.template to files that are
        # actually loaded as units (i.e. not marked dont_load).
        dont_load = False
        if core and truthy(core.get("dont_load")):
            dont_load = True

        template = None
        if (self.use_template and not dont_load
                and not is_template_entry(name) and not is_modinfo(name)):
            tname = self.find_template(name)
            if tname and tname in self.parsed:
                template = self.raw_merged(tname)

        # high priority first: own file, then copyFrom targets last-to-first,
        # then all-units.template (engine's iniobj.put merge order).
        acc = OrderedDict()
        merge_into(acc, own)                       # keep own's own flags
        for target in reversed(copy_targets):
            merge_into(acc, target, inherited=True)
        if template is not None:
            merge_into(acc, template, inherited=True)

        self.stack.discard(name)
        self.raw_cache[name] = acc
        self.copyfrom_ok[name] = copyfrom_ok
        return acc

    def resolve(self, name):
        """Final effective content for one file."""
        acc = copy_sections(self.raw_merged(name))
        self.resolve_section_copies(acc)
        globals_ = self.collect_globals(acc)
        self.resolve_macros(acc, globals_)
        if self.copyfrom_ok.get(name, True) and "core" in acc and "copyFrom" in acc["core"]:
            del acc["core"]["copyFrom"]
        # Once everything is expanded, the macro definitions are no longer
        # needed.  Keep them only when some ${...} could not be resolved, so
        # the engine can still finish the job at runtime.
        has_macro = any("${" in v for sec in acc.values() for v in sec.values())
        if not has_macro:
            for sec in acc.values():
                for key in list(sec.keys()):
                    if key.startswith("@define ") or key.startswith("@global "):
                        del sec[key]
        return acc

    @staticmethod
    def section_targets(name, sec):
        """Collect the sections this section inherits from.

        '@copyFromSection' lists explicit section names; the plain 'copyFrom'
        key used inside indexed parts (turret_R, leg_2, projectile_3, ...)
        names a sibling by suffix: `[leg_2] copyFrom: 1` -> `leg_1`.
        """
        targets = []
        explicit = sec.get("@copyFromSection")
        if explicit and explicit.strip().upper() != "IGNORE":
            for token in explicit.split(","):
                token = token.strip()
                if token:
                    targets.append(token)
        sibling = sec.get("copyFrom")
        if sibling and "_" in name:
            prefix = name[:name.index("_")]
            for token in sibling.split(","):
                token = token.strip()
                if token:
                    targets.append(prefix + "_" + token)
        return targets

    def resolve_section_copies(self, sections):
        resolved = {}
        visiting = set()

        def ensure(name):
            if name in resolved:
                return
            if name in visiting:
                return
            sec = sections.get(name)
            if sec is None:
                resolved[name] = None
                return
            visiting.add(name)
            copied = OrderedDict()
            targets = self.section_targets(name, sec)
            all_found = bool(targets)
            for token in targets:
                ensure(token)
                tsec = resolved.get(token)
                if tsec:
                    copied.update(tsec)     # later target wins
                else:
                    all_found = False
            # merge-control flags belong to the section itself, not to the
            # sections it copies from.
            copied.pop("@copyFrom_skipThisSection", None)
            # engine order: own keys first (original positions), then the
            # missing keys copied from the target section(s).
            merged = OrderedDict()
            for k, v in sec.items():
                if k in ("@copyFromSection", "copyFrom"):
                    continue
                merged[k] = v
            for k, v in copied.items():
                merged.setdefault(k, v)
            if not all_found:
                # keep an unresolved directive so the engine can retry it
                for key in ("@copyFromSection", "copyFrom"):
                    if key in sec:
                        merged[key] = sec[key]
            resolved[name] = merged
            visiting.discard(name)

        for name in list(sections.keys()):
            ensure(name)
        for name, value in resolved.items():
            if value is not None:
                sections[name] = value

    def collect_globals(self, sections):
        globals_ = {}
        for sec in sections.values():
            for key, value in sec.items():
                if key.startswith("@global ") and value.strip() != "IGNORE":
                    globals_[key[len("@global "):]] = value
        return globals_

    def resolve_macros(self, sections, globals_):
        for _ in range(10):                     # bounded passes for nesting
            changed = False
            for secname, sec in sections.items():
                for key, value in list(sec.items()):
                    new = self.expand(value, secname, sec, sections, globals_)
                    if new is not None and new != value:
                        sec[key] = new
                        changed = True
            for key, value in list(globals_.items()):
                new = self.expand(value, None, {}, sections, globals_)
                if new is not None and new != value:
                    globals_[key] = new
                    changed = True
            if not changed:
                break

    def expand(self, value, secname, sec, sections, globals_):
        if "${" not in value:
            return value
        out = []
        i = 0
        n = len(value)
        while True:
            start = value.find("${", i)
            if start < 0:
                out.append(value[i:])
                break
            out.append(value[i:start])
            end = value.find("}", start + 2)
            if end < 0:
                out.append(value[start:])
                break
            replacement = self.resolve_matcher(
                value[start + 2:end], secname, sec, sections, globals_)
            if replacement is None:
                out.append(value[start:end + 1])   # leave unresolved
            else:
                out.append(replacement)
            i = end + 1
        return "".join(out)

    def resolve_matcher(self, inner, secname, sec, sections, globals_):
        inner = inner.strip()
        result = []
        pos = 0
        failed = False

        def lookup(token):
            if token in _MATH_FUNCS:
                return token
            if "." in token:
                secn, key = token.split(".", 1)
                table = sec if (secn == "section" or secn == secname) else sections.get(secn)
                if table is None or key not in table:
                    return None
                return table[key]
            value = sec.get("@define " + token)
            if value is None:
                value = globals_.get(token)
            if value is None:
                value = sec.get(token)
            return value

        for match in _IDENT_RE.finditer(inner):
            result.append(inner[pos:match.start()])
            token = match.group(0)
            value = lookup(token)
            if value is None:
                failed = True
                result.append(token)
            else:
                result.append(value)
            pos = match.end()
        result.append(inner[pos:])
        text = "".join(result)
        if failed:
            return None

        if any(ch in text for ch in "+-*/%^()"):
            py = text.replace("^", "**")
            value = try_eval(py)
            if value is not None:
                return format_number(value)
        return text


def detect_root(names):
    candidates = sorted((n for n in names if is_modinfo(n)), key=len)
    if candidates:
        top = candidates[0]
        return top[:len(top) - len("mod-info.txt")]
    return ""



def safe_member_path(root, name):
    """Join root + name, refusing to escape root."""
    parts = [p for p in name.replace("\\", "/").split("/") if p not in ("", ".")]
    if any(p == ".." for p in parts):
        raise ValueError("unsafe path: " + name)
    return os.path.join(root, *parts)


def read_text(data):
    """Decode text files as UTF-8, falling back to common GBK."""
    for enc in ("utf-8-sig", "utf-8", "gbk", "big5"):
        try:
            return data.decode(enc)
        except UnicodeDecodeError:
            continue
    return data.decode("utf-8", "replace")


def open_zip(path):
    return zipfile.ZipFile(path, "r")


# --------------------------------------------------------------------------
# Core
# --------------------------------------------------------------------------

class Progress(object):
    """A tiny in-place progress bar written to stderr.

    Disabled automatically when stderr is not a terminal (e.g. piped), so it
    never pollutes captured output.
    """

    def __init__(self, enabled=None, stream=None):
        self.stream = stream or sys.stderr
        if enabled is None:
            try:
                enabled = bool(self.stream.isatty())
            except Exception:
                enabled = False
        self.enabled = enabled
        self.label = ""
        self.total = 1
        self.current = 0
        self._last = 0

    def phase(self, label, total):
        self.label = label
        self.total = max(int(total), 1)
        self.current = 0
        self._draw()

    def step(self, n=1):
        self.current += n
        if self.enabled:
            self._draw()

    def _draw(self):
        if not self.enabled:
            return
        width = 28
        frac = min(self.current / self.total, 1.0)
        filled = int(frac * width)
        bar = "#" * filled + "-" * (width - filled)
        text = "\r%-10s [%s] %3d%% (%d/%d)" % (
            self.label, bar, int(frac * 100), self.current, self.total)
        pad = " " * (self._last - len(text)) if self._last > len(text) else ""
        self.stream.write(text + pad)
        self.stream.flush()
        self._last = len(text)

    def finish(self):
        if self.enabled:
            self._draw()
            self.stream.write("\n")
            self.stream.flush()
        self._last = 0


class Stats(object):
    def __init__(self):
        self.files = 0
        self.dirs = 0
        self.renamed = 0
        self.ini_files = 0
        self.ini_sections = 0
        self.ini_keys = 0
        self.unresolved = 0
        self.removed_templates = 0
        self.stripped = 0
        self.invalid_keys = 0
        self.invalid_examples = []
        self.keylist = None
        self.repaired = False
        self.paths_fixed = 0


def _add_entry(files, dirs, taken, raw_name, data):
    """Add one member, undoing the fake-folder 'name/' disguise."""
    # A zero-length entry ending in '/' is a real folder.  An entry that ends
    # in '/' but *carries data* is a file disguised as a folder.
    if raw_name.endswith("/") and len(data) == 0:
        dirs.add(raw_name.rstrip("/"))
        return
    logical = raw_name.rstrip("/")
    # avoid collisions after removing the disguise
    if logical in taken:
        base, ext = os.path.splitext(logical)
        k = 1
        while ("%s~%d%s" % (base, k, ext)) in taken:
            k += 1
        logical = "%s~%d%s" % (base, k, ext)
    taken.add(logical)
    files.append((logical, data, raw_name != logical))


def collect(zf, progress=None):
    """Read all entries of a healthy zip, undoing the fake-folder disguise.

    Returns (files, dirs) where files is a list of
        (logical_name, data_bytes, was_modified)
    """
    files = []
    dirs = set()
    taken = set()
    infos = zf.infolist()
    if progress:
        progress.phase("读取", len(infos))
    for info in infos:
        if progress:
            progress.step()
        fn = info.filename
        if fn.endswith("/") and info.file_size == 0:
            dirs.add(fn.rstrip("/"))
            continue
        _add_entry(files, dirs, taken, fn, zf.read(info))
    return files, dirs


# --------------------------------------------------------------------------
# Repair reader for zips whose header fields (version / crc / sizes / flags)
# were mangled but whose local data and central directory offsets are intact.
# --------------------------------------------------------------------------

_ZC64_LOCATOR = b"PK\x06\x07"
_ZC64_EOCD = b"PK\x06\x06"
_EOCD = b"PK\x05\x06"


def _find_eocd(f, size):
    """Return (cd_offset, cd_size, count) using EOCD / zip64 EOCD."""
    span = min(size, 65536 + 22)
    f.seek(size - span)
    tail = f.read(span)
    idx = tail.rfind(_EOCD)
    if idx < 0:
        raise ValueError("end of central directory not found")
    (sig, disk, cd_disk, n_disk, n_total, cd_size,
     cd_off, comment) = struct.unpack_from("<IHHHHIIH", tail, idx)
    if cd_off == 0xFFFFFFFF or cd_size == 0xFFFFFFFF or n_total == 0xFFFF:
        # zip64: the locator sits 20 bytes before the EOCD
        loc_off = size - span + idx - 20
        if loc_off >= 0:
            f.seek(loc_off)
            loc = f.read(20)
            if loc[:4] == _ZC64_LOCATOR:
                z_off = struct.unpack_from("<Q", loc, 8)[0]
                f.seek(z_off)
                z = f.read(56)
                if z[:4] == _ZC64_EOCD:
                    (_, _, _, _, _, _, n_total,
                     cd_size, cd_off) = struct.unpack_from("<QHHIIQQQQ", z, 4)
    return cd_off, cd_size, n_total


def _parse_central_directory(f, cd_off, cd_size):
    """Return [(name_bytes, local_header_offset, method), ...]."""
    f.seek(cd_off)
    data = f.read(cd_size)
    entries = []
    off = 0
    while off + 46 <= len(data) and data[off:off + 4] == b"PK\x01\x02":
        fields = struct.unpack_from("<IHHHHHHIIIHHHHHII", data, off)
        nlen, elen, clen = fields[10], fields[11], fields[12]
        name = data[off + 46:off + 46 + nlen]
        entries.append((name, fields[16], fields[4]))
        off += 46 + nlen + elen + clen
    if not entries:
        raise ValueError("central directory is not readable")
    return entries


def _inflate_stream(f, offset):
    """Inflate a raw deflate stream starting at offset, until it ends."""
    f.seek(offset)
    d = zlib.decompressobj(-15)
    out = []
    while not d.eof:
        chunk = f.read(1 << 20)
        if not chunk:
            break
        out.append(d.decompress(chunk))
    return b"".join(out)


def collect_repaired(path, progress=None):
    """Read a zip with mangled header fields (repair reader).

    Uses the (intact) local-header offsets from the central directory to
    locate each member, then inflates the raw data stream so the bogus
    size/crc/version fields are ignored.
    """
    size = os.path.getsize(path)
    files = []
    dirs = set()
    taken = set()
    with open(path, "rb") as f:
        cd_off, cd_size, _ = _find_eocd(f, size)
        if not cd_off or cd_off >= size:
            cd_off, cd_size, _ = _find_eocd(f, size)
        entries = _parse_central_directory(f, cd_off, cd_size)
        entries.sort(key=lambda e: e[1])
        if progress:
            progress.phase("修复", len(entries))
        for i, (cname, lho, _cm) in enumerate(entries):
            if progress:
                progress.step()
            f.seek(lho)
            hdr = f.read(30)
            if len(hdr) < 30 or hdr[:4] != b"PK\x03\x04":
                continue
            (_, _, flags, method, _, _, _,
             _csize, _usize, nlen, elen) = struct.unpack("<IHHHHHIIIHH", hdr)
            local_name = f.read(nlen)
            f.read(elen)
            data_off = lho + 30 + nlen + elen
            next_off = entries[i + 1][1] if i + 1 < len(entries) else cd_off
            name = local_name if nlen == len(cname) else cname
            try:
                if method == 8:
                    data = _inflate_stream(f, data_off)
                else:
                    length = max(0, next_off - data_off)
                    f.seek(data_off)
                    data = f.read(length)
                    # drop a trailing data descriptor if present
                    if len(data) >= 16 and data[-16:-12] == b"PK\x07\x08":
                        data = data[:-16]
            except zlib.error:
                continue
            _add_entry(files, dirs, taken, name.decode("utf-8", "replace"),
                       data)
    return files, dirs


def _decode_maybe_text(data):
    """Return decoded text when the bytes look like a text file, else None."""
    if not data or b"\x00" in data[:8192]:
        return None
    for enc in ("utf-8-sig", "utf-8", "gbk", "big5"):
        try:
            return data.decode(enc)
        except UnicodeDecodeError:
            continue
    return None


def _as_config(name, data, require_known=False):
    """Parse a member as an INI config, or return None.

    With ``require_known`` the content must contain at least one section the
    engine recognises, which keeps binary files from being mistaken for ini.
    """
    text = _decode_maybe_text(data)
    if text is None:
        return None
    sections = parse_ini(text)
    if not sections:
        return None
    if require_known and not any(is_recognized_section(s) for s in sections):
        return None
    return sections


def _copyfrom_targets(sections):
    """Return the [core] copyFrom paths of one file."""
    core = sections.get("core")
    if not core:
        return []
    value = core.get("copyFrom")
    if not value or value.strip().upper() == "IGNORE":
        return []
    return [t.strip() for t in value.split(",") if t.strip()]


def build_config_sections(files, resolve, use_template, progress=None):
    """Parse (and optionally expand) every config file.

    Returns ``(sections_by_name, unresolved_count)``.  Without --resolve the
    sections are just the modified files; with --resolve they are the final
    effective content.

    A file is treated as a config when its name says so (.ini/.template/
    mod-info.txt) or when it is referenced by a ``[core] copyFrom`` (directly
    or transitively).  The latter also covers protected packs that store
    configs under obfuscated names without a normal extension.
    """
    by_name = {name: data for name, data, _ in files}
    member_names = list(by_name)
    root = detect_root(member_names)
    resolver = Resolver(OrderedDict(), root, use_template)
    resolver.index = FileIndex(member_names)

    parsed = OrderedDict()
    # pass 1: names that are config files, plus extensionless members whose
    # content parses as ini (protected packs hide configs this way)
    if progress:
        progress.phase("解析", len(files))
    for name, data, _ in files:
        if progress:
            progress.step()
        # Without --resolve-template the all-units.template files are left
        # untouched, so the engine keeps applying them at runtime.
        if resolve and not use_template and is_template_entry(name):
            continue
        if is_text_config(name):
            parsed[name] = parse_ini(read_text(data))
        elif "." not in name.rsplit("/", 1)[-1]:
            sections = _as_config(name, data, require_known=True)
            if sections is not None:
                parsed[name] = sections

    # pass 2: follow [core] copyFrom references transitively
    work = list(parsed)
    while work:
        name = work.pop()
        for target in _copyfrom_targets(parsed[name]):
            tname = resolver.resolve_target(target, name)
            if not tname or tname in parsed:
                continue
            if progress:
                progress.step()
            sections = _as_config(tname, by_name.get(tname, b""))
            if sections is not None:
                parsed[tname] = sections
                work.append(tname)

    if not resolve:
        return parsed, 0

    if progress:
        progress.phase("展开", len(parsed))
    resolver = Resolver(parsed, detect_root(parsed.keys()), use_template)
    out = OrderedDict()
    unresolved = 0
    for name in parsed:
        if progress:
            progress.step()
        sections = resolver.resolve(name)
        out[name] = sections
        if "${" in dump_ini(sections):
            unresolved += 1
    return out, unresolved


def process(in_path, out_dir=None, out_rwmod=None, modify_ini=True,
            list_only=False, add_dirs=True, resolve=False,
            resolve_template=False, keylist_mode=None, strip_invalid_keys=False,
            repair=False, progress=None):
    if progress is None:
        progress = Progress()
    stats = Stats()
    base = os.path.splitext(os.path.basename(in_path))[0]
