        out_rwmod = os.path.join(
            os.path.dirname(os.path.abspath(in_path)),
            base + "_modified.rwmod")

    files = None
    if not repair:
        try:
            zf = open_zip(in_path)
            try:
                files, dirs = collect(zf, progress)
            finally:
                zf.close()
            stats.repaired = False
        except Exception:
            files = None
    if files is None:
        # Broken/mangled zip header -> use the repair reader.
        files, dirs = collect_repaired(in_path, progress)
        stats.repaired = True

