            files, resolve, resolve_template, progress)
        stats.ini_files = len(sections_by_name)
        stats.ini_sections = sum(len(secs) for secs in sections_by_name.values())
        stats.ini_keys = sum(
            len(sec) for secs in sections_by_name.values() for sec in secs.values())
        stats.stripped = strip_unknown_sections(sections_by_name)
        member_names = [n for n, _, _ in files]
        stats.paths_fixed = normalize_reference_paths(
            sections_by_name, member_names, detect_root(member_names))

        # ---- key-name validity check (only on request) ----------------------
        if keylist_mode:
            text = None
            if keylist_mode == "external":
                path = find_external_keylist(in_path)
                if path:
                    text = read_text(open(path, "rb").read())
                    stats.keylist = path
                else:
                    print("warning: keyList.txt not found, key check skipped",
                          file=sys.stderr)
            else:
                try:
                    text = internal_keylist_text()
                    stats.keylist = "(internal)"
                except ValueError as exc:
                    print("warning: %s" % exc, file=sys.stderr)
            if text:

metadata.preview:
        validator = KeyValidator(text)
